from pathlib import Path
p=Path('index.html'); s=p.read_text()
css=r'''
.avatar-builder{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(340px,.95fr);gap:18px}.upload-zone{position:relative;min-height:190px;border:1.5px dashed #746cff66;border-radius:16px;background:linear-gradient(145deg,#7065ff0c,#2bd8ff08);display:grid;place-items:center;text-align:center;padding:18px;overflow:hidden;transition:.25s}.upload-zone:hover{border-color:#6edfff;box-shadow:inset 0 0 40px #2bd8ff0c}.upload-zone input{position:absolute;inset:0;opacity:0;cursor:pointer}.upload-zone img{max-width:100%;max-height:220px;border-radius:13px;box-shadow:0 15px 35px #0008}.upload-icon{font-size:32px;margin-bottom:8px}.voice-drop{min-height:130px}.voice-drop audio{position:relative;z-index:2;width:100%}.pipeline{display:grid;gap:10px;margin:18px 0}.pipeline-step{display:flex;align-items:center;gap:12px;padding:11px 13px;border:1px solid var(--line);border-radius:12px;background:#070a1766;color:var(--muted)}.pipeline-step .step-no{width:28px;height:28px;border-radius:9px;display:grid;place-items:center;background:#292e4e;color:#c9ceed;font-weight:800}.pipeline-step.active{border-color:#746aff;color:#fff;box-shadow:0 0 22px #7065ff1c}.pipeline-step.active .step-no{background:linear-gradient(135deg,#7665ff,#29d7ef);color:#fff}.pipeline-step.done{border-color:#2ad89d55;color:#9ff2d3}.pipeline-step.done .step-no{background:#158965;color:#fff}.avatar-preview{min-height:470px;display:flex;flex-direction:column}.avatar-stage{flex:1;min-height:300px;border-radius:16px;background:radial-gradient(circle at 50% 35%,#242e58,#090b17 66%);display:grid;place-items:center;position:relative;overflow:hidden}.avatar-stage:after{content:"";position:absolute;inset:auto 10% 0;height:1px;background:#6e7cff55;box-shadow:0 0 40px 15px #5d67ff32}.avatar-stage video{width:100%;height:100%;object-fit:contain;position:relative;z-index:1}.avatar-placeholder{text-align:center;color:var(--muted);z-index:1}.avatar-placeholder .face{font-size:70px;filter:drop-shadow(0 0 30px #6f67ff88);animation:orbFloat 5s ease-in-out infinite}.consent{padding:11px 13px;border:1px solid #ffcc6644;background:#523b162e;border-radius:11px;color:#e5c681;font-size:12px}.quality-badge{display:inline-flex;align-items:center;gap:7px;padding:6px 10px;border-radius:99px;background:#14b87a18;color:#6de8b9;border:1px solid #2adb9e3b;font-size:12px}@media(max-width:900px){.avatar-builder{grid-template-columns:1fr}.avatar-preview{min-height:380px}}
'''
s=s.replace('</style>',css+'</style>')
s=s.replace('<button class="nav-btn" data-page="vimax"><span class="nav-icon">🎬</span>Video Studio</button>','<button class="nav-btn" data-page="vimax"><span class="nav-icon">🎬</span>Video Studio</button><button class="nav-btn" data-page="talking-avatar"><span class="nav-icon">◉</span>Talking Avatar</button>')
page=r'''
    <section id="page-talking-avatar" class="page"><div class="head"><div class="row"><h1>Talking AI Avatar Studio</h1><span class="quality-badge">✦ HIGH QUALITY</span></div><p>Upload your portrait and a clean sample of your own voice. AI clones the voice from your sample, reads your script, then animates your photo with natural lip-sync and gestures.</p></div><div class="avatar-builder"><form class="card" id="talkingAvatarForm"><h3>1. Your avatar photo</h3><p>Use a clear, front-facing portrait with good lighting.</p><div class="upload-zone" id="portraitZone"><input id="portraitFile" type="file" accept="image/png,image/jpeg,image/webp" required><div id="portraitHint"><div class="upload-icon">◎</div><strong>Upload your photo</strong><p>JPG, PNG or WebP · max 12 MB</p></div><img id="portraitPreview" class="hidden" alt="Portrait preview"></div><h3 style="margin-top:20px">2. Your voice sample</h3><p>Upload 10–30 seconds of clean speech without music or background noise.</p><div class="upload-zone voice-drop" id="voiceZone"><input id="voiceSampleFile" type="file" accept="audio/*" required><div id="voiceHint"><div class="upload-icon">≋</div><strong>Upload voice sample</strong><p>MP3, WAV, M4A or OGG · max 30 MB</p></div><audio id="voiceSamplePreview" controls class="hidden"></audio></div><div class="field" style="margin-top:14px"><label class="label">What is said in the sample? <span style="color:var(--muted)">(recommended)</span></label><textarea id="voiceRefText" class="textarea" style="min-height:72px" placeholder="Type the exact words spoken in your sample…"></textarea></div><h3 style="margin-top:20px">3. Script to speak</h3><div class="field"><textarea id="avatarScript" class="textarea" maxlength="5000" placeholder="Write or paste what your avatar should say…" required></textarea><div class="row between"><small id="avatarChars">0 / 5,000</small><button type="button" class="link" id="writeAvatarScript">AI write my script</button></div></div><details><summary>Quality & model settings</summary><div class="grid g2" style="margin-top:13px"><div class="field"><label class="label">Voice model</label><select id="avatarVoiceModel" class="select"><option value="f5-tts-space">F5-TTS Voice Clone (HQ)</option><option value="f5-tts-replicate">F5-TTS GPU</option><option value="coqui-xtts">XTTS v2</option><option value="edge-tts">Standard voice (no clone)</option></select></div><div class="field"><label class="label">Avatar model</label><select id="avatarVideoModel" class="select"><option value="fal-echomimic">EchoMimic v3 (best)</option><option value="fal-sadtalker">SadTalker</option><option value="fal-liveportrait">LivePortrait</option></select></div><div class="field"><label class="label">Language</label><select id="avatarLanguage" class="select"><option value="en">English</option><option value="ur">Urdu</option><option value="hi">Hindi</option><option value="es">Spanish</option><option value="ar">Arabic</option></select></div><div class="field"><label class="label">Voice speed</label><select id="avatarSpeed" class="select"><option value="0.9">Calm</option><option value="1" selected>Natural</option><option value="1.1">Energetic</option></select></div></div></details><label class="check consent"><input id="avatarConsent" type="checkbox" required> I confirm this is my own photo and voice, or I have explicit permission to use them.</label><button class="btn full" id="createAvatarBtn">Generate talking avatar</button></form><div class="card avatar-preview"><div class="row between"><div><h3>Production preview</h3><p>Your generated avatar video will appear here.</p></div><span id="avatarStatus" class="chip">Ready</span></div><div id="avatarStage" class="avatar-stage"><div id="avatarPlaceholder" class="avatar-placeholder"><div class="face">◉</div><strong>Your AI avatar</strong><p>Photo + voice + script → video</p></div></div><div class="pipeline"><div class="pipeline-step" data-avatar-step="1"><span class="step-no">1</span><div><strong>Upload assets</strong><small>Secure portrait and voice reference</small></div></div><div class="pipeline-step" data-avatar-step="2"><span class="step-no">2</span><div><strong>Clone & generate voice</strong><small>High-quality speech from your script</small></div></div><div class="pipeline-step" data-avatar-step="3"><span class="step-no">3</span><div><strong>Animate portrait</strong><small>Lip-sync, face and natural gestures</small></div></div><div class="pipeline-step" data-avatar-step="4"><span class="step-no">4</span><div><strong>Render video</strong><small>Final downloadable MP4</small></div></div></div><div id="avatarResult" class="result"></div></div></div></section>
'''
s=s.replace('    <section id="page-vimax"',page+'\n    <section id="page-vimax"')
s=s.replace("history:'History',chat:'AI Chat'};","history:'History',chat:'AI Chat','talking-avatar':'Talking Avatar'};")
# Functions before auth mode
needle='function authMode(reg)'
js=r'''function avatarStep(n,status='active'){document.querySelectorAll('[data-avatar-step]').forEach(el=>{const x=Number(el.dataset.avatarStep);el.classList.toggle('done',x<n);el.classList.toggle('active',x===n)});$('#avatarStatus').textContent=status}
function filePreview(input,preview,hint,type){input.onchange=()=>{const f=input.files[0];if(!f)return;const url=URL.createObjectURL(f);$(preview).classList.remove('hidden');$(hint).classList.add('hidden');if(type==='image')$(preview).src=url;else $(preview).src=url}}
async function pollAvatarJob(id){for(let i=0;i<30;i++){await new Promise(r=>setTimeout(r,5000));const d=await api(`/api/generation/jobs/${id}`);const job=d.job||{};$('#avatarStatus').textContent=`Rendering · ${job.status||'processing'}`;if(d.done){if(job.status==='failed')throw new Error(job.error||'Avatar rendering failed');return job}}return null}
function avatarVideoUrl(data){const candidates=[data?.url,data?.video_url,data?.output?.url,data?.output?.video?.url,data?.result?.url,data?.result?.video_url];if(Array.isArray(data?.output))candidates.unshift(data.output[0]);return candidates.find(x=>typeof x==='string')||''}
'''
s=s.replace(needle,js+needle)
# Events before chat events
needle2="$('#chatForm').onsubmit"
events=r'''filePreview($('#portraitFile'),'#portraitPreview','#portraitHint','image');filePreview($('#voiceSampleFile'),'#voiceSamplePreview','#voiceHint','audio');$('#avatarScript').oninput=e=>$('#avatarChars').textContent=`${e.target.value.length.toLocaleString()} / 5,000`;$('#writeAvatarScript').onclick=async()=>{const topic=prompt('What should the avatar talk about?');if(!topic)return;try{toast('AI is writing the script…');const d=await api('/api/script/write',{method:'POST',body:JSON.stringify({topic,genre:'presenter',length:'short',tone:'conversational'})});$('#avatarScript').value=d.script||'';$('#avatarScript').dispatchEvent(new Event('input'))}catch(e){toast(e.message,true)}};
$('#talkingAvatarForm').onsubmit=async e=>{e.preventDefault();const btn=$('#createAvatarBtn'),portrait=$('#portraitFile').files[0],voice=$('#voiceSampleFile').files[0];if(!portrait||!voice)return toast('Upload both your photo and voice sample',true);busy(btn,true);$('#avatarResult').innerHTML='';try{avatarStep(1,'Uploading assets');const fd=new FormData();fd.append('portrait',portrait);fd.append('voice_sample',voice);const assets=await api('/api/talking-avatar/assets',{method:'POST',body:fd});const imageUrl=assets.portrait_url||assets.portrait_data_uri,refAudio=assets.voice_sample_url||assets.voice_sample_data_uri;if(!imageUrl||!refAudio)throw new Error('Could not prepare uploaded media');avatarStep(2,'Generating your voice');const voiceOut=await api('/api/generate/tts',{method:'POST',body:JSON.stringify({model:$('#avatarVoiceModel').value,text:$('#avatarScript').value,audio_url:refAudio,ref_audio:refAudio,ref_text:$('#voiceRefText').value,language:$('#avatarLanguage').value,speed:Number($('#avatarSpeed').value)})});const audioUrl=voiceOut.url||voiceOut.data_uri||voiceOut.audio_url;if(!audioUrl)throw new Error('Voice provider did not return audio. Try F5-TTS or add a configured voice provider.');avatarStep(3,'Animating your portrait');let videoOut=await api('/api/generate/avatar',{method:'POST',body:JSON.stringify({model:$('#avatarVideoModel').value,image_url:imageUrl,audio_url:audioUrl,prompt:'Natural high quality talking avatar, accurate lip sync, subtle head movement and realistic expression'})});if(videoOut.job_id){avatarStep(4,'Rendering video');const job=await pollAvatarJob(videoOut.job_id);if(job)videoOut=job}const videoUrl=avatarVideoUrl(videoOut);if(videoUrl){$('#avatarPlaceholder').classList.add('hidden');$('#avatarStage').innerHTML=`<video src="${esc(videoUrl)}" controls autoplay playsinline></video>`;$('#avatarResult').innerHTML=`<a class="btn full" href="${esc(videoUrl)}" target="_blank" download>Download avatar video</a>`;avatarStep(5,'Video ready');document.querySelectorAll('[data-avatar-step]').forEach(x=>x.classList.add('done'));toast('Talking avatar video is ready')}else{renderOutput('#avatarResult',videoOut);avatarStep(4,videoOut.status||'Generation submitted');toast('Avatar job submitted. Result details are shown below.')}}catch(e){$('#avatarStatus').textContent='Error';$('#avatarResult').innerHTML=`<div class="notice">${esc(e.message)}</div>`;toast(e.message,true)}finally{busy(btn,false)}};
'''
s=s.replace(needle2,events+needle2)
p.write_text(s)
print('talking avatar UI added')
